package onnx

import (
	"encoding/binary"
	"encoding/json"
	"math"
	"os"
	"path/filepath"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// reference is the onnxruntime result for a fixed random input, so the pure-Go
// executor can be checked numerically rather than only structurally. The files
// are regenerated by amane-work/onnxprobe/make_ref.py.
type reference struct {
	Model   string           `json:"model"`
	Input   string           `json:"input"`
	Shape   []int            `json:"shape"`
	Outputs map[string][]int `json:"outputs"`
}

func readFloats(t *testing.T, path string) []float32 {
	t.Helper()
	data, err := os.ReadFile(path)
	require.NoError(t, err)
	require.Zero(t, len(data)%4, "%s: raw data length is not a multiple of 4", path)
	out := make([]float32, len(data)/4)
	for i := range out {
		out[i] = math.Float32frombits(binary.LittleEndian.Uint32(data[i*4:]))
	}
	return out
}

func readReference(t *testing.T, name string) reference {
	t.Helper()
	data, err := os.ReadFile(filepath.Join("testdata", name+"_meta.json"))
	require.NoError(t, err)
	var ref reference
	require.NoError(t, json.Unmarshal(data, &ref))
	return ref
}

// compareAgainstReference runs the model on the same input onnxruntime used and
// reports the largest absolute difference.
func compareAgainstReference(t *testing.T, modelFile, refName string, tolerance float32) {
	t.Helper()
	ref := readReference(t, refName)

	raw, err := os.ReadFile(modelFile)
	if err != nil {
		t.Skipf("model not available: %v", err)
	}
	model, err := Load(raw)
	require.NoError(t, err)

	input := &Tensor{
		Shape: ref.Shape,
		Data:  readFloats(t, filepath.Join("testdata", refName+"_input.bin")),
	}
	got, err := model.Run(input)
	require.NoError(t, err)

	require.NotEmpty(t, ref.Outputs)
	for name, wantShape := range ref.Outputs {
		want := readFloats(t, filepath.Join("testdata", refName+"_"+name+".bin"))
		tensor, ok := got[name]
		require.True(t, ok, "missing output %s", name)
		assert.Equal(t, wantShape, tensor.Shape, "output %s shape", name)
		require.Len(t, tensor.Data, len(want), "output %s length", name)

		maxDiff := float32(0)
		for i := range want {
			if d := float32(math.Abs(float64(tensor.Data[i] - want[i]))); d > maxDiff {
				maxDiff = d
			}
		}
		assert.LessOrEqualf(t, maxDiff, tolerance, "output %s differs from onnxruntime by %v", name, maxDiff)
		t.Logf("output %-4s shape=%-12v max|diff|=%.6g", name, tensor.Shape, maxDiff)
	}
}

// TestGenderMatchesOnnxRuntime checks the gender net end to end.
func TestGenderMatchesOnnxRuntime(t *testing.T) {
	compareAgainstReference(t, "../models/face_detect_genderage.onnx", "gender96", 1e-5)
}

// TestScrfdMatchesOnnxRuntime checks the detector end to end. The tolerance is
// looser than the gender net because the graph is 158 nodes deep and float32
// accumulation order differs from ort's SIMD kernels.
func TestScrfdMatchesOnnxRuntime(t *testing.T) {
	compareAgainstReference(t, "../models/face_detect_scrfd.onnx", "scrfd64", 1e-3)
}

